* { box-sizing: border-box; }

body {
     margin: 0;
     padding: 32px 16px;
     font-family: Georgia, "Times New Roman", serif;

    background: #ffffff;
    display: flex;
    justify-content: center;
}

.bai-viet {
    width: min(800px, 100%);
}

.bai-viet h1 {
    margin: 0;
    text-align: center;
    color: #1565C0;
    text-transform: uppercase;
    font-size: 26px;
    line-height: 1.3;
}

.bai-viet h1 span {
    display: block;
    font-size: 0.7em;
}

.anh-banner {
    display: block;
    width: 100%;
    max-height: 280px;
    object-fit: cover;
    border-radius: 8px;
    margin: 16px 0;
}

.bai-viet p {
    margin: 14px 0;
    line-height: 1.85;
    text-align: justify;
    display: flow-root;
}

  .bai-viet p::first-letter {
      float: left;
      font-size: 3rem;
      line-height: 0.85;
      font-weight: 700;
      color: #C62828;
      padding: 0.1rem 0.35rem 0 0;
  }

  .thanh-phu {
      background: #1565C0;
      color: #ffffff;
      text-align: right;
      padding: 6px 12px;
      font-size: 15px;
      margin: 16px 0;
      border-radius: 3px;
  }
